(() => {
'use strict';
const $ = (s) => document.querySelector(s);
const escapeHTML = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tex = s => `\\(${escapeHTML(s)}\\)`;
const texBlock = s => `<div class="formula">\\[${escapeHTML(s)}\\]</div>`;
const basename = s => s.replace(/\.pdf$/i,'').replace(/\s*\(1\)\s*/g,' ').replace(/-MAT415.*/i,'').trim();
const docHref = s => 'materiales/'+encodeURIComponent(s);
const getLesson = id => LESSONS.find(l=>l.id===id) || LESSONS[0];
const lessonQuestions = id => QUESTIONS.filter(q=>q.lesson===id);
const pct = (x,y) => y>0?Math.round(100*x/y):0;
const fromStore=()=>{try{return JSON.parse(localStorage.getItem('deriva-mat415-v1')||'{}')}catch{return {}}};
const old=fromStore();
const st = {tab:'inicio',lesson:'s1',unit:'Todos',filter:'Todos',notes:old.notes||{},done:old.done||[],attempts:old.attempts||[],bookmarks:old.bookmarks||[],flashKnown:old.flashKnown||[],search:false,query:'',topic:'Todos',reviewOnly:false,lessonFocus:null,examType:6};
st.examTier=1;st.practiceTier=1;st.miniScores=old.miniScores||{};
const miniSessions={},lessonDetailed={};
st.customHistory=Array.isArray(old.customHistory)?old.customHistory:[];
let pr={q:null,chosen:null,hint:false,expanded:false};
const lessonSteps={};
const EXAM_STORE_KEY='deriva-mat415-active-exam-v4';
let exam=(()=>{try{const x=JSON.parse(localStorage.getItem(EXAM_STORE_KEY)||'null');return x&&Array.isArray(x.questions)&&Array.isArray(x.answers)&&Array.isArray(x.works)?x:null}catch{return null}})();
function saveExam(){try{if(exam)localStorage.setItem(EXAM_STORE_KEY,JSON.stringify(exam));else localStorage.removeItem(EXAM_STORE_KEY)}catch{}}
const openAnswerMode=()=>!!exam&&exam.tier>=4;
const isExamAnswered=i=>openAnswerMode()?!!String(exam.freeAnswers?.[i]||'').trim():exam.answers[i]!==null;
const QUESTION_TASKS={"ts1_4":"Indica el orden, la linealidad y si la ecuación es homogénea.","ts1_5":"Indica el orden y explica por qué la ecuación es lineal o no lineal.","ts2_4":"Encuentra la solución particular que satisface y(0)=0.","ts2_5":"Factoriza primero y²−1 y encuentra la solución particular.","ts3_4":"Resuelve la ecuación usando la sustitución u=y/x.","ts3_5":"Al separar variables, ¿qué solución especial podrías perder al dividir?","ts3e_4":"Verifica si la ecuación M dx + N dy = 0 es exacta.","ts3e_5":"Comprueba la exactitud y encuentra la solución implícita.","ts4_4":"Normaliza la ecuación y determina su factor integrante.","ts4_5":"Normaliza, aplica el factor integrante y encuentra la solución general.","ts4b_4":"Con v=1/y, escribe la ecuación diferencial transformada.","ts4b_5":"¿Qué solución singular debe comprobarse antes de dividir por y²?","ts6_4":"Determina la función de desintegración que satisface el valor inicial.","ts6_5":"Calcula la tasa k usando los dos valores de población.","ts6m_4":"Calcula el volumen V(t) a partir de los caudales de entrada y salida.","ts6m_5":"Determina el intervalo físico donde el volumen se mantiene positivo.","ts7_4":"Calcula el Wronskiano y determina si las funciones son independientes.","ts7_5":"Calcula el Wronskiano de seno y coseno usando sus derivadas.","ts7r_4":"Aplica la regla del producto y calcula y′ en función de v.","ts7r_5":"Deriva dos veces y=xv y determina y″.","ts8_4":"Halla las raíces características y escribe la solución general real.","ts8_5":"Factoriza la característica e identifica la solución con raíz doble.","ts8a_4":"Encuentra la forma correcta de la particular atendiendo a la resonancia.","ts8a_5":"Calcula una solución particular mediante coeficientes indeterminados.","ts9_4":"Calcula el Wronskiano necesario para variación de parámetros.","ts9_5":"Normaliza la ecuación y calcula u₁′ usando el Wronskiano.","ts9c_4":"Resuelve la ecuación de Cauchy–Euler mediante y=x^m.","ts9c_5":"Halla la ecuación indicial y escribe la solución para raíz doble.","ts10_4":"Resuelve el problema de valor inicial del oscilador armónico.","ts10_5":"Simplifica dividiendo por 2 y resuelve el problema inicial.","ts12_4":"Calcula la transformada de Laplace aplicando linealidad.","ts12_5":"Desarrolla el cuadrado antes de calcular su transformada de Laplace.","ts13_4":"Transforma la EDO, incorpora y(0) y despeja Y(s).","ts13_5":"Transforma las derivadas con sus datos iniciales y despeja Y(s).","ts14_4":"Evalúa la función escalón unitario para el tiempo indicado.","ts14_5":"Reescribe t=(t−2)+2 y calcula la transformada desplazada.","ts15_4":"Evalúa la integral de convolución para las funciones dadas.","ts15_5":"Calcula la convolución integrando e^τ·e^(t−τ)."};
function examTask(q){
 if(QUESTION_TASKS[q.id])return QUESTION_TASKS[q.id];
 const ans=String(q.choices?.[q.correct]||'');const why=String(q.why||'');
 if(q.lesson==='s1')return 'Determina el orden y clasifica la ecuación diferencial.';
 if(/\\mu|μ/.test(ans))return 'Encuentra el factor integrante correcto.';
 if(/\\text\{/.test(ans))return 'Identifica la propiedad o afirmación correcta.';
 if(/(?:^|\\,)(?:y|P|V)\s*(?:\\?\(|=)/.test(ans)||/y\(x\)=|P\(t\)=/.test(ans))return 'Obtén la solución que satisface el enunciado.';
 if(/exacta|parcial/i.test(why))return 'Verifica la exactitud o determina la función potencial.';
 if(/sustituci[oó]n|Bernoulli/i.test(why))return 'Identifica la sustitución o transformación correcta.';
 if(/ra[ií]ces|discriminante|caracter[ií]stica/i.test(why))return 'Calcula las raíces o determina la forma de la solución.';
 if(/laplace|transformad/i.test(why))return 'Aplica la propiedad de Laplace y determina la respuesta.';
 return 'Determina el resultado o la afirmación matemática correcta.';
}
function examWorksheet(){const i=exam.index,mode=openAnswerMode();return `<section class="worksheet"><button class="worksheet-toggle" data-action="exam-work-toggle" aria-expanded="${exam.workOpen?'true':'false'}"><span>✎ &nbsp; Área de trabajo</span><span class="muted small">${exam.works[i]?.trim()?'Con apuntes guardados':'Tu desarrollo, sin pistas'} &nbsp; ${exam.workOpen?'−':'+'}</span></button>${exam.workOpen?`<div class="worksheet-body"><label class="field" for="exam-work"><span>Desarrolla las operaciones de esta pregunta</span></label><textarea id="exam-work" data-exam-work="${i}" spellcheck="false" placeholder="1. Identifico el método…
2. Simplifico o factorizo…
3. Resuelvo…
4. Compruebo sustituyendo…">${escapeHTML(exam.works[i]||'')}</textarea><div class="math-keyboard"><span>Insertar:</span>${["y'","y''","∫","²","√","±","→","ln","C"].map(t=>`<button type="button" class="math-key" data-action="exam-insert" data-symbol="${escapeHTML(t)}">${escapeHTML(t)}</button>`).join('')}</div><p class="tiny muted">Tus apuntes se conservan al cambiar de pregunta. No se corrigen automáticamente.</p></div>`:''}</section>`}
function examWrittenResponse(){const i=exam.index;return `<div class="response-panel"><label for="exam-free" class="response-label">Tu respuesta final <span class="muted small">(escribe una expresión o explicación)</span></label><textarea id="exam-free" data-exam-free="${i}" spellcheck="false" placeholder="Escribe aquí tu solución, clasificación o resultado…">${escapeHTML(exam.freeAnswers?.[i]||'')}</textarea><p class="tiny muted">Sin opciones. Al finalizar compararás tu respuesta con la solución de referencia y la evaluarás.</p></div>`}
function exportExamWork(){if(!exam)return;const doc=exam.questions.map((q,i)=>`PREGUNTA ${i+1} — ${getLesson(q.lesson).name}\nObjetivo: ${examTask(q)}\nEnunciado: ${q.prompt}\nRespuesta: ${openAnswerMode()?exam.freeAnswers?.[i]||'(sin respuesta)':exam.answers[i]===null?'(sin respuesta)':q.choices[exam.answers[i]]}\nDesarrollo:\n${exam.works[i]||'(sin apuntes)'}\n${exam.result?`Referencia: ${q.choices[q.correct]}\nMotivo: ${q.why}`:''}`).join('\n\n'+'-'.repeat(45)+'\n\n');const blob=new Blob([`DERIVA · SIMULACRO ${TIERS[exam.tier-1].name}\n\n`+doc],{type:'text/plain;charset=utf-8'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='deriva-mi-simulacro.txt';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);}

let toastId=null;
const nav=[['inicio','⌂','Inicio'],['ruta','◫','Ruta de estudio'],['metodos','∑','Métodos'],['constructor','✍','Constructor'],['herramientas','◇','Herramientas'],['practica','✎','Practicar'],['examenes','◷','Simulacros'],['biblioteca','▤','Biblioteca']];
const units=Object.keys(UNIT_META);
const save=()=>{try{localStorage.setItem('deriva-mat415-v1',JSON.stringify({notes:st.notes,done:st.done,attempts:st.attempts,bookmarks:st.bookmarks,flashKnown:st.flashKnown,customHistory:st.customHistory||[],miniScores:st.miniScores}))}catch{showToast('No fue posible guardar en este navegador.')}};
const doneCount=(unit)=>LESSONS.filter(l=>l.unit===unit && st.done.includes(l.id)).length;
const successCount=()=>st.attempts.filter(a=>a.correct).length;
const latestAnswered=(id)=>[...st.attempts].reverse().find(a=>a.q===id);
function showToast(msg){let t=$('#toast');if(!t){t=document.createElement('div');t.id='toast';t.className='toast';document.body.appendChild(t)}t.textContent=msg;t.classList.remove('hidden');clearTimeout(toastId);toastId=setTimeout(()=>t.classList.add('hidden'),3200)}
let mjQueue=Promise.resolve();
function typeset(){const mj=window.MathJax;if(mj&&typeof mj.typesetPromise==='function'){mjQueue=mjQueue.catch(()=>{}).then(()=>mj.typesetPromise([$('#content')].filter(Boolean))).catch(()=>{});} }
function setTab(tab){st.tab=tab;if(tab==='practica'&&!pr.q)randomQuestion();window.scrollTo({top:0,behavior:'instant'});render()}
function openLesson(id){st.lesson=id;setTab('leccion')}
function randomQuestion(){let arr=QUESTIONS.filter(q => (st.topic==='Todos'||getLesson(q.lesson).unit===st.topic)&&((q.tier||1)===st.practiceTier));
 if(st.lessonFocus)arr=arr.filter(q=>q.lesson===st.lessonFocus);
 if(st.reviewOnly){const missed=st.attempts.filter(a=>!a.correct).map(a=>a.q);arr=arr.filter(q=>missed.includes(q.id))}
 if(!arr.length){pr={q:null,chosen:null,hint:false,expanded:false};return}
 const alternative=arr.filter(q=>q.id!==pr.q?.id);const pool=alternative.length?alternative:arr;
 // favor less-answered questions without excluding material forever
 const ordered=pool.map(q=>({q,tries:st.attempts.filter(a=>a.q===q.id).length,r:Math.random()})).sort((a,b)=>a.tries-b.tries||a.r-b.r);
 const head=ordered.slice(0,Math.max(1,Math.ceil(ordered.length/3)));
 pr={q:head[Math.floor(Math.random()*head.length)].q,chosen:null,hint:false,expanded:false};
}
function header(title){const tab=st.tab==='leccion'?'Lección':nav.find(n=>n[0]===st.tab)?.[2]||'Inicio';return `<header class="topbar"><div class="crumb">MATEMÁTICA IV &nbsp; / &nbsp; <b>${escapeHTML(title||tab)}</b></div><div class="top-actions"><button class="keyhint" data-action="search-open" aria-label="Buscar contenidos"><span>⌕ &nbsp; Buscar contenido</span><kbd>Ctrl K</kbd></button><div class="avatar" aria-label="Tu espacio de estudio">∑</div></div></header>`}
function sidebar(){const weeks=[...new Set(LESSONS.map(l=>l.week))];return `<aside class="sidebar"><div class="brand"><div class="brand-mark">∂</div><div><div class="brand-name">deriva.</div><div class="brand-sub">ACADEMIA · MAT 415</div></div></div><div class="side-label">Tu espacio</div>${nav.map(([id,ic,name])=>`<button class="nav-btn ${st.tab===id||st.tab==='leccion'&&id==='ruta'?'active':''}" data-action="tab" data-tab="${id}" title="${name}" aria-label="${name}"><span class="nav-icon">${ic}</span><span class="nav-text">${name}</span></button>`).join('')}<div class="side-label">Semanas</div><div class="side-weeks">${weeks.map(w=>`<button class="week-link ${getLesson(st.lesson).week===w&&st.tab==='leccion'?'active':''}" data-action="week" data-week="${w}" title="Semana ${w}">${w}</button>`).join('')}</div><div class="side-bottom"><strong>Tu recorrido</strong><div class="mini-bar"><span style="width:${pct(st.done.length,LESSONS.length)}%"></span></div><small>${st.done.length} de ${LESSONS.length} lecciones terminadas</small></div></aside>`}
function svgGraph(){let w=320,h=130,lines=[];for(let i=0;i<3;i++){let points=[];for(let x=0;x<=w;x+=3){let y=65-35*Math.exp(-x/350)*Math.sin((x/32)+(i*.4));points.push(`${x},${y.toFixed(2)}`)}lines.push(`<polyline points="${points.join(' ')}" fill="none" stroke="${['#8fdcdd','#8da5f6','#52749b'][i]}" stroke-width="${i===0?2.8:1.35}" opacity="${1-i*.22}"/>`)}return `<svg viewBox="0 0 320 130" class="hero-graph" aria-label="Curvas de soluciones a ecuaciones diferenciales" role="img"><defs><pattern id="grid" width="32" height="32" patternUnits="userSpaceOnUse"><path d="M 32 0 L 0 0 0 32" fill="none" stroke="#52657e" stroke-width=".6" opacity=".30"/></pattern></defs><rect width="320" height="130" fill="url(#grid)"/>${lines.join('')}</svg>`}
function home(){const score=st.attempts.length?pct(successCount(),st.attempts.length):0;const next=LESSONS.find(l=>!st.done.includes(l.id))||LESSONS[LESSONS.length-1];return `<div class="eyebrow">TU CAMPUS DE ESTUDIO</div><section class="hero"><div><div class="tag mint">Matemática IV · UES</div><h1 class="h1" style="margin-top:18px">Las ecuaciones se<br/>aprenden <span style="color:#a9bcff">resolviendo.</span></h1><p class="desc">Teoría de tus guías, procedimientos paso a paso y práctica real. Desde ecuaciones de primer orden hasta la transformada de Laplace.</p><div class="btn-row"><button class="btn primary" data-action="open-lesson" data-id="${next.id}">Continuar: Semana ${next.week} &nbsp; →</button><button class="btn ghost" data-action="tab" data-tab="practica">Empezar a practicar</button></div></div><div class="hero-art"><div class="art-formula">${tex('\\frac{dy}{dx}=f(x,y)')}</div>${svgGraph()}<div class="tiny muted" style="text-align:center;letter-spacing:.14em">MODELAR · RESOLVER · VERIFICAR</div></div></section><section class="hero-stats"><div class="stat"><div class="stat-top">Lecciones completadas</div><div class="stat-value">${st.done.length}<span class="muted" style="font-size:15px;font-weight:400"> / ${LESSONS.length}</span></div><div class="stat-foot">${pct(st.done.length,LESSONS.length)}% de la ruta de aprendizaje</div></div><div class="stat"><div class="stat-top">Ejercicios respondidos</div><div class="stat-value">${st.attempts.length}</div><div class="stat-foot">Banco de ${QUESTIONS.length} preguntas</div></div><div class="stat"><div class="stat-top">Precisión global</div><div class="stat-value">${st.attempts.length?score+'%':'—'}</div><div class="stat-foot">Respuestas acertadas al practicar</div></div></section><div class="section-head"><div><h2>Aprende por bloques</h2><p>Avanza siguiendo el orden de las guías semanales.</p></div><button class="btn flat" data-action="tab" data-tab="ruta">Ver toda la ruta →</button></div><section class="grid-courses">${units.map((u,i)=>{let ls=LESSONS.filter(l=>l.unit===u);return `<button class="course-card" data-action="unit" data-unit="${escapeHTML(u)}"><div class="course-icon" style="color:${UNIT_META[u].color}">${['∑','∫','ƒ','λ','ℒ'][i]}</div><h3>${u}</h3><p>${UNIT_META[u].desc}</p><div class="course-foot"><span>${ls.length} lecciones</span><span>${doneCount(u)}/${ls.length} completas</span></div><div class="progress-mini"><span style="width:${pct(doneCount(u),ls.length)}%"></span></div></button>`}).join('')}</section><div class="section-head"><div><h2>Tu próxima sesión</h2><p>Una forma sencilla de estudiar durante 40 minutos.</p></div></div><div class="two-col"><div class="panel"><div class="eyebrow">SESIÓN RECOMENDADA</div><h3 class="h3">${escapeHTML(next.name)}</h3><p class="desc">${escapeHTML(next.summary)}</p><div class="btn-row"><button class="btn primary" data-action="open-lesson" data-id="${next.id}">Abrir lección →</button><button class="btn ghost" data-action="tab" data-tab="examenes">Simulacro</button></div></div><div class="panel"><div class="eyebrow">PLAN 40 MIN</div><div class="timeline"><div class="timeline-item"><div class="timeline-dot done">✓</div><div><strong>10 min · Teoría</strong><p>Lee la regla y reconoce el tipo de ecuación.</p></div></div><div class="timeline-item"><div class="timeline-dot">2</div><div><strong>15 min · Ejemplo</strong><p>Resuelve antes de descubrir cada paso.</p></div></div><div class="timeline-item"><div class="timeline-dot">3</div><div><strong>15 min · Entrenamiento</strong><p>Practica sin mirar la solución.</p></div></div></div></div></div>`}
function route(){const list=LESSONS.filter(l=>st.filter==='Todos'||l.unit===st.filter);return `<div class="eyebrow">PROGRAMA POR SEMANAS</div><h1 class="h1">Ruta de aprendizaje</h1><div class="filterbar">${['Todos',...units].map(u=>`<button class="filter ${st.filter===u?'active':''}" data-action="filter" data-filter="${u}">${u}</button>`).join('')}</div><section class="lesson-grid">${list.map(l=>`<div class="lesson-tile"><div class="tile-top"><span class="week-tiny">SEMANA ${l.week} · ${escapeHTML(l.unit)}</span><span class="tag ${l.level==='Avanzado'?'orange':l.level==='Inicial'?'mint':'grey'}">${l.level}</span></div><h3 class="tile-title">${escapeHTML(l.name)}</h3><div class="tile-summary">${escapeHTML(l.summary)}</div><div class="tile-foot"><span class="${st.done.includes(l.id)?'status-dot':''}">${st.done.includes(l.id)?'✓ Completada':'○ Por estudiar'} · ${lessonQuestions(l.id).length} ejercicios</span><button data-action="open-lesson" data-id="${l.id}">Estudiar →</button></div></div>`).join('')}</section>`}
function asideLesson(l){let count=lessonQuestions(l.id).length;return `<aside class="lesson-aside"><div class="panel"><div class="eyebrow">TU AVANCE</div><h3 class="h3">¿Ya dominas este tema?</h3><p class="desc small">Marca la lección cuando hayas entendido el método y resuelto un ejercicio sin ayuda.</p><div class="btn-row"><button class="btn ${st.done.includes(l.id)?'ghost':'primary'}" style="width:100%" data-action="toggle-done" data-id="${l.id}">${st.done.includes(l.id)?'✓ Lección completada':'Marcar como aprendida'}</button></div></div><div class="panel"><div class="eyebrow">PRÁCTICA DEL TEMA</div><p class="desc small">${count} preguntas del banco relacionadas con este método.</p><div class="btn-row"><button class="btn ghost" data-action="practice-lesson" data-id="${l.id}">Practicar ahora →</button></div></div><div class="panel"><div class="eyebrow">MATERIAL ORIGINAL</div><p class="small muted">${escapeHTML(l.source)} · págs. ${escapeHTML(l.pages)}</p><a class="doc-link" href="${docHref(l.source)}" target="_blank" rel="noopener"><div class="pdficon" style="width:29px;height:34px;font-size:9px">PDF</div><span>Consultar guía</span><span style="margin-left:auto">↗</span></a></div></aside>`}
function lessonView(){const l=getLesson(st.lesson);const shown=lessonSteps[l.id]||0;const pos=LESSONS.findIndex(x=>x.id===l.id);const prev=LESSONS[pos-1],next=LESSONS[pos+1];return `<button class="btn flat sm" data-action="tab" data-tab="ruta">← Volver a las lecciones</button><div style="margin-top:19px"><span class="tag">SEMANA ${l.week}</span><span class="tag grey" style="margin-left:7px">${escapeHTML(l.unit)}</span></div><h1 class="h1" style="margin-top:15px">${escapeHTML(l.name)}</h1><p class="desc maxw">${escapeHTML(l.summary)}</p><section class="lesson-layout"><div class="reading"><article class="panel"><div class="eyebrow">01 / TEORÍA ESENCIAL</div><h2 class="h2">¿Qué debes comprender?</h2><p>${escapeHTML(l.concept)}</p>${texBlock(l.formula)}<p class="small muted">Referencia de la guía: ${escapeHTML(l.extra)}.</p></article><article class="panel"><div class="eyebrow">02 / MÉTODO DE RESOLUCIÓN</div><h2 class="h2">Procedimiento</h2><p>Aplica los pasos en este orden. Cada método se basa en el procedimiento utilizado en el material de clase.</p><div class="steps">${l.recipe.map((s,i)=>`<div class="step"><span class="num">${i+1}</span><span class="plain-step">${escapeHTML(s)}</span></div>`).join('')}</div></article><article class="panel"><div class="eyebrow">03 / EJEMPLO RESUELTO</div><h2 class="h2">Ejemplo paso a paso</h2><p>Intenta desarrollar el ejercicio en tu cuaderno antes de avanzar.</p>${texBlock(l.example)}<div class="steps">${l.steps.slice(0,shown).map((s,i)=>`<div class="step"><span class="num">${i+1}</span><div class="mathline">${tex(s)}</div></div>`).join('')}${shown===0?`<div class="empty">La solución está oculta. Intenta resolver el primer paso y comprueba después tu procedimiento.</div>`:''}</div><div class="btn-row">${shown<l.steps.length?`<button class="btn primary sm" data-action="reveal-lesson-step" data-id="${l.id}">Mostrar paso ${shown+1} →</button><button class="btn ghost sm" data-action="reveal-lesson-all" data-id="${l.id}">Ver todos los pasos</button>`:`<button class="btn ghost sm" data-action="hide-lesson-steps" data-id="${l.id}">↻ Repetir sin ayuda</button>`}</div>${shown===l.steps.length?`<div class="formula accent">${tex(l.result)}</div>`:''}<div class="note-box"><strong>Evita este error</strong><div>${escapeHTML(l.error)}</div></div></article><article class="panel"><div class="eyebrow">04 / MIS APUNTES</div><h2 class="h2">Cuaderno personal</h2><p>Guarda dudas, fórmulas o trucos del tema. Se conserva en este navegador, sin necesidad de cuenta.</p><textarea class="notes" id="notes" data-lesson="${l.id}" placeholder="Ejemplo: No olvidar el factor integrante y las condiciones iniciales...">${escapeHTML(st.notes[l.id]||'')}</textarea><p class="tiny muted">Guardado automático en tu dispositivo.</p></article><div class="lesson-nav">${prev?`<button class="btn ghost" data-action="open-lesson" data-id="${prev.id}">← ${escapeHTML(prev.name)}</button>`:'<span></span>'}${next?`<button class="btn primary" data-action="open-lesson" data-id="${next.id}">${escapeHTML(next.name)} →</button>`:'<button class="btn primary" data-action="tab" data-tab="examenes">Hacer simulacro →</button>'}</div></div>${asideLesson(l)}</section>`}
function methods(){const grouped=units.map(u=>({u,ls:LESSONS.filter(l=>l.unit===u)}));return `<div class="eyebrow">ELIGE EL PROCEDIMIENTO</div><h1 class="h1">Biblioteca de métodos</h1><div class="btn-row"><button class="btn ghost sm" data-action="tab" data-tab="herramientas">Factorización, geometría y trigonometría →</button></div><div class="panel" style="margin:23px 0;background:linear-gradient(125deg,#1c3040,#172336)"><div class="eyebrow">ÁRBOL DE DECISIÓN RÁPIDO</div><div class="grid-courses" style="grid-template-columns:repeat(auto-fit,minmax(185px,1fr))"><div><strong>¿Es de primer orden?</strong><p class="small muted">Prueba separables → homogéneas → exactas → lineales → Bernoulli.</p></div><div><strong>¿Coeficientes constantes?</strong><p class="small muted">Construye la ecuación característica y clasifica sus raíces.</p></div><div><strong>¿Tiene condiciones iniciales?</strong><p class="small muted">Considera Laplace, especialmente con escalones o entradas por tramos.</p></div></div></div>${grouped.map(({u,ls})=>`<div class="section-head"><div><h2>${u}</h2><p>${UNIT_META[u].desc}</p></div></div><section class="lesson-grid">${ls.map(l=>`<div class="lesson-tile" style="min-height:135px"><div class="tile-top"><span class="week-tiny">SEMANA ${l.week}</span><span class="tag grey">${l.level}</span></div><h3 class="tile-title">${escapeHTML(l.name)}</h3><div class="tile-summary">${escapeHTML(l.recipe[0])}</div><div class="tile-foot"><span>Fórmula · ejemplo · pasos</span><button data-action="open-lesson" data-id="${l.id}">Ver método →</button></div></div>`).join('')}</section>`).join('')}`}

function quizCard(q,examMode=false){const selected=examMode?(exam?.answers?.[exam.index]??null):pr.chosen,locked=selected!==null&&!examMode;
 return `<div class="question-panel"><div class="question-count"><span class="week-tiny">${escapeHTML(getLesson(q.lesson).name)} · Nivel ${q.tier||1}</span>${!examMode?`<button class="btn flat sm" data-action="bookmark" data-id="${q.id}">${st.bookmarks.includes(q.id)?'★ Guardado':'☆ Guardar'}</button>`:''}</div><h2 class="quiz-instruction">${escapeHTML(examTask(q))}</h2><div class="question-math">${tex(q.prompt)}</div><div class="choice-grid">${q.choices.map((choice,i)=>`<button class="choice ${examMode&&selected===i?'exam-selected':locked&&i===q.correct?'correct':locked&&i===selected?'wrong':''}" data-action="${examMode?'exam-answer':'answer'}" data-index="${i}" ${locked?'disabled':''}><span class="letter">${'ABCD'[i]}</span><span class="option-math">${tex(choice)}</span></button>`).join('')}</div>${!examMode&&!locked?`<div class="practice-tools"><button class="btn ghost sm" data-action="hint">${pr.hint?'Ocultar':'Ver pista'}</button><button class="btn flat sm" data-action="next-question">Saltar →</button></div>${pr.hint?`<div class="hint">${escapeHTML(q.tip)}</div>`:''}`:''}${!examMode&&locked?`<div class="feedback ${selected===q.correct?'':'bad'}"><strong>${selected===q.correct?'✓ Correcta':'✗ Incorrecta'}</strong><p>${escapeHTML(q.why)}</p>${q.craft?`<div class="craft-notice"><strong>Carpintería:</strong> ${escapeHTML(q.craft)}</div>`:''}</div><div class="practice-tools"><button class="btn ghost" data-action="expand-method">${pr.expanded?'Ocultar procedimiento':'Explicar método'}</button><button class="btn primary" data-action="next-question">Siguiente →</button></div>${pr.expanded?`<div class="panel flat" style="margin-top:14px"><h3>Razonamiento</h3><p>${escapeHTML(q.why)}</p>${getLesson(q.lesson).recipe.map((s,i)=>`<div class="quiz-step"><b>${i+1}.</b> ${escapeHTML(s)}</div>`).join('')}<div class="btn-row"><button class="btn ghost sm" data-action="open-lesson" data-id="${q.lesson}">Ver lección →</button></div></div>`:''}`:''}</div>`;
}


function practice(){if(!pr.q)randomQuestion();let q=pr.q;return `<div class="eyebrow">PRÁCTICA</div><h1 class="h1">Ejercicios graduados</h1><div class="filterbar">${TIERS.map(t=>`<button class="filter ${st.practiceTier===t.id?'active':''}" data-action="practice-tier" data-id="${t.id}">${escapeHTML(t.name)}</button>`).join('')}</div><div class="filterbar small-filters">${['Todos',...units].map(u=>`<button class="filter ${st.topic===u?'active':''}" data-action="topic" data-topic="${u}">${u}</button>`).join('')}</div>${st.lessonFocus?`<div class="tag mint" style="margin-bottom:14px">${escapeHTML(getLesson(st.lessonFocus).name)} <button class="reset-tag" data-action="clear-focus">✕</button></div>`:''}<div class="practice-shell"><div>${q?quizCard(q):'<div class="empty">No hay ejercicios con estos filtros.</div>'}</div><div class="right-mini"><div class="panel"><div class="eyebrow">RENDIMIENTO</div><div class="progress-num">${st.attempts.length?pct(successCount(),st.attempts.length)+'%':'—'}</div><p class="small muted">${successCount()} / ${st.attempts.length} aciertos</p></div><div class="panel"><button class="btn ${st.reviewOnly?'primary':'ghost'} sm" data-action="toggle-review">${st.reviewOnly?'✓ Solo errores':'Repetir fallados'}</button></div><div class="panel"><button class="btn ghost sm" data-action="export">Exportar progreso ↗</button></div></div></div>`}


function exams(){
 if(exam?.result){
  const manual=openAnswerMode(),marks=exam.selfMarks||[],reviewed=marks.filter(x=>x!==null).length,hit=manual?marks.filter(x=>x===true).length:exam.questions.filter((q,i)=>exam.answers[i]===q.correct).length;
  return `<button class="btn flat" data-action="exam-reset">← Simulacros</button>
   <section class="testhero" style="margin-top:20px"><div class="eyebrow">${escapeHTML(TIERS[exam.tier-1].name)} · REVISIÓN</div><h1 class="h1">${manual?`${hit} / ${exam.questions.length}`:`${hit} / ${exam.questions.length}`}</h1><p class="muted">${manual?`${reviewed} de ${exam.questions.length} autocorregidas${reviewed<exam.questions.length?' · Calificación provisional':''}`:`${pct(hit,exam.questions.length)}% de aciertos`}</p><div class="btn-row"><button class="btn primary" data-action="exam-reset">Otro simulacro</button><button class="btn ghost" data-action="exam-export-work">Exportar mi desarrollo ↓</button></div></section>
   <h2 class="h2 section-space">Corrección de respuestas</h2><div class="review-list">${exam.questions.map((q,i)=>`<article class="review-card reviewed-card"><div class="week-tiny">PREGUNTA ${i+1} · ${manual?(marks[i]===true?'✓ ACERTADA':marks[i]===false?'✗ PARA REPASAR':'PENDIENTE'):exam.answers[i]===q.correct?'✓ CORRECTA':'✗ INCORRECTA'} · ${escapeHTML(getLesson(q.lesson).name)}</div><h3 class="quiz-instruction">${escapeHTML(examTask(q))}</h3><div class="mathline">${tex(q.prompt)}</div>${manual?`<div class="review-block"><b>Tu respuesta</b><p class="user-answer">${escapeHTML(exam.freeAnswers[i]||'Sin respuesta')}</p></div>`:`<p><span class="muted">Tu respuesta:</span> ${exam.answers[i]===null?'Sin respuesta':tex(q.choices[exam.answers[i]])}</p>`}<div class="review-block reference"><b>Respuesta de referencia</b><div class="mathline">${tex(q.choices[q.correct])}</div></div><p><strong>¿Por qué?</strong> ${escapeHTML(q.why)}</p>${q.craft?`<div class="craft-notice"><b>Carpintería previa:</b> ${escapeHTML(q.craft)}</div>`:''}${exam.works[i]?.trim()?`<details class="review-work"><summary>Mi área de trabajo</summary><pre>${escapeHTML(exam.works[i])}</pre></details>`:''}${manual?`<div class="self-check"><span>Después de comparar:</span><button class="btn sm ${marks[i]===true?'primary':'ghost'}" data-action="exam-self-check" data-index="${i}" data-mark="yes" aria-pressed="${marks[i]===true}">✓ La resolví bien</button><button class="btn sm ${marks[i]===false?'primary':'ghost'}" data-action="exam-self-check" data-index="${i}" data-mark="no" aria-pressed="${marks[i]===false}">↺ Necesito repasar</button></div>`:''}<button class="btn flat sm" data-action="open-lesson" data-id="${q.lesson}">Ver método de la lección →</button></article>`).join('')}</div>`;
 }
 if(!exam){return `<div class="eyebrow">EVALUACIONES</div><h1 class="h1">Pruebas por dificultad</h1><section class="exam-tier-grid">${TIERS.map(t=>`<button class="exam-tier ${st.examTier===t.id?'active':''}" data-action="exam-tier" data-id="${t.id}"><span class="level-label">Nivel ${t.id}</span><strong>${escapeHTML(t.name)}</strong><small>${escapeHTML(t.desc)}</small><span>${t.count} ejercicios · ${t.minutes} min</span><small>${t.id>=4?'✎ Respuesta escrita · autocorrección':'◉ Selección múltiple'}</small></button>`).join('')}</section><div class="btn-row"><button class="btn primary" data-action="exam-start">Iniciar ${escapeHTML(TIERS[st.examTier-1].name)} →</button></div><h2 class="h2 section-space">Parciales originales</h2><div class="library-grid">${EXAMS.map(f=>fileTile(f,'Solución original')).join('')}</div>`;}
 const q=exam.questions[exam.index],count=exam.questions.filter((_,i)=>isExamAnswered(i)).length,seconds=Math.max(0,Math.ceil((exam.end-Date.now())/1000)),manual=openAnswerMode();
 return `<div class="eyebrow">${escapeHTML(TIERS[exam.tier-1].name)} · SIMULACRO ${manual?'· RESPUESTA ESCRITA':''}</div><div class="exam-session-head"><h1 class="h1">Pregunta ${exam.index+1} / ${exam.questions.length}</h1><div class="timer" id="countdown" aria-label="Tiempo restante">${formatTime(seconds)}</div></div><div class="exam-progress">${exam.questions.map((_,i)=>`<i class="${isExamAnswered(i)?'answered':i===exam.index?'current':''}"></i>`).join('')}</div><div class="exam-current">
 ${manual?`<div class="question-panel"><div class="question-count"><span class="week-tiny">${escapeHTML(getLesson(q.lesson).name)} · Nivel ${q.tier||1}</span><span class="muted small">Sin opciones</span></div><h2 class="quiz-instruction">${escapeHTML(examTask(q))}</h2><div class="question-math">${tex(q.prompt)}</div>${examWrittenResponse()}</div>`:quizCard(q,true)}
 ${examWorksheet()}<div class="practice-tools"><span class="muted small">${count} de ${exam.questions.length} respondidas · respuestas guardadas en este dispositivo</span><div class="btn-row">${exam.index>0?'<button class="btn ghost" data-action="exam-prev">← Anterior</button>':''}${exam.index<exam.questions.length-1?'<button class="btn primary" data-action="exam-next">Siguiente →</button>':'<button class="btn primary" data-action="exam-finish">Finalizar prueba</button>'}</div></div>
 <div class="exam-question-nav" aria-label="Ir a una pregunta">${exam.questions.map((_,i)=>`<button data-action="exam-goto" data-index="${i}" class="${exam.index===i?'active':''} ${isExamAnswered(i)?'completed':''}" title="Pregunta ${i+1}${isExamAnswered(i)?' respondida':''}">${i+1}</button>`).join('')}</div></div>`;
}
function library(){return `<div class="eyebrow">BIBLIOTECA DEL CURSO</div><h1 class="h1">Material original</h1><div class="section-head"><div><h2>Guías semanales</h2><p>${FILES.length} documentos · curso MAT 415 / ECD 115</p></div></div><section class="library-grid">${FILES.sort((a,b)=>(parseInt(a.match(/\d+/)?.[0]||0)-parseInt(b.match(/\d+/)?.[0]||0))).map(f=>fileTile(f,'Guía de clase')).join('')}</section><div class="section-head"><div><h2>Parciales resueltos</h2><p>${EXAMS.length} documentos con desarrollo de problemas.</p></div></div><section class="library-grid">${EXAMS.map(f=>fileTile(f,'Solución de evaluación')).join('')}</section><div class="panel" style="margin-top:23px"><h3 class="h3">Tus datos, bajo tu control</h3><p class="desc">Lecciones, respuestas y notas se guardan en el almacenamiento local del navegador. No se envían a ningún servidor.</p><div class="btn-row"><button class="btn ghost" data-action="export">Exportar mi progreso (.json)</button><button class="btn danger" data-action="reset-progress">Borrar progreso local</button></div></div>`}
function fileTile(f,type){return `<a class="file-card" href="${docHref(f)}" target="_blank" rel="noopener"><div class="pdficon">PDF</div><div style="min-width:0;overflow-wrap:anywhere"><strong>${escapeHTML(basename(f))}</strong><small>${type}</small></div><span class="arr">↗</span></a>`}

// Componentes de la segunda versión de Deriva.

function renderedProcess(steps,shown,detailed=false){return `<div class="deep-list">${steps.slice(0,shown).map((s,i)=>`<article class="deep-step"><div class="deep-head"><span class="deep-number">${String(i+1).padStart(2,'0')}</span><strong>${escapeHTML(s.title||`Paso ${i+1}`)}</strong></div><div class="deep-formula">${texBlock(s.math)}</div><div class="reason"><span>¿Por qué este paso?</span><p>${escapeHTML(s.why||'')}</p></div>${detailed?`<div class="detail deep-origin"><span>DE DÓNDE SALE</span><p>${escapeHTML(s.detail||'Se obtiene aplicando la operación indicada a la expresión anterior, sin cambiar la igualdad. Comprueba el resultado invirtiendo la operación o derivando.')}</p></div>`:s.detail?`<div class="detail"><span>CLAVE</span> ${escapeHTML(s.detail)}</div>`:''}</article>`).join('')}</div>`}
function explorer(id){const parts=TERM_ATLAS[id]||[];if(!parts.length)return '';return `<div class="math-explorer"><div class="explorer-head"><span class="eyebrow">ECUACIÓN INTERACTIVA</span><span class="muted tiny">Pasa el cursor o selecciona un término</span></div><div class="math-fragments" role="group" aria-label="Partes de la ecuación">${parts.map(([formula,label,description,role])=>`<button type="button" class="math-token role-${escapeHTML(role)}" aria-label="${escapeHTML(label)}: ${escapeHTML(description)}"><span class="token-math">${tex(formula)}</span><span class="token-tooltip" role="tooltip"><b>${escapeHTML(label)}</b><span>${escapeHTML(description)}</span></span></button>`).join('')}</div><div class="symbol-legend"><span class="x-key">x / t: independiente o tiempo</span><span class="y-key">y / P / A: función o cantidad</span><span class="d-key">′ / ″: derivadas</span></div></div>`}
function getMini(id){if(!miniSessions[id]){
 const source=QUESTIONS.filter(q=>q.lesson===id&&q.tier===1).slice(0,1);
 const extra=NEW_QUESTIONS.filter(q=>q.lesson===id).sort((a,b)=>a.tier-b.tier);
 miniSessions[id]={questions:[...source,...extra].slice(0,5),index:0,answers:{},hint:false};
 }return miniSessions[id];}
function miniQuiz(l){const session=getMini(l.id),qs=session.questions,i=session.index;
 if(i>=qs.length){const score=qs.filter((q,j)=>session.answers[j]===q.correct).length;return `<article class="panel mini-panel" id="mini-quiz"><div class="eyebrow">05 / MINICUESTIONARIO</div><h2 class="h2">${score} / ${qs.length} correctas</h2><p class="muted">${score===qs.length?'Perfecto.':`Repasa los ${qs.length-score} ejercicios fallados.`}</p><div class="btn-row"><button class="btn primary" data-action="mini-retry" data-id="${l.id}">Reintentar las 5 preguntas</button><button class="btn ghost" data-action="practice-lesson" data-id="${l.id}">Más práctica →</button></div><div class="mini-review">${qs.map((q,j)=>`<div class="mini-review-row"><span>${session.answers[j]===q.correct?'✓':'✗'} ${j+1}.</span> ${tex(q.choices[q.correct])}<small>${escapeHTML(q.why)}</small></div>`).join('')}</div></article>`;}
 const q=qs[i],choice=session.answers[i],answered=choice!==undefined;
 return `<article class="panel mini-panel" id="mini-quiz"><div class="eyebrow">05 / MINICUESTIONARIO</div><div class="mini-header"><h2 class="h2">Comprueba lo aprendido</h2><b>${i+1} / ${qs.length}</b></div><div class="mini-dots">${qs.map((q,j)=>`<i class="${j===i?'active':j<i?'done':''}"></i>`).join('')}</div><div class="mini-level"><span>Nivel ${q.tier||1} · ${escapeHTML(TIERS[(q.tier||1)-1].name)}</span></div><p class="quiz-instruction">${escapeHTML(examTask(q))}</p><div class="mini-question">${texBlock(q.prompt)}</div><div class="mini-choices">${q.choices.map((ch,j)=>`<button class="mini-choice ${answered&&(j===q.correct?'correct':j===choice?'wrong':'')}" data-action="mini-answer" data-id="${l.id}" data-choice="${j}" ${answered?'disabled':''}><span class="letter">${'ABCD'[j]}</span>${tex(ch)}</button>`).join('')}</div>${answered?`<div class="mini-feedback"><strong>${choice===q.correct?'Respuesta correcta':'Corrección'}</strong><p>${escapeHTML(q.why)}</p>${q.craft?`<div class="craft-notice"><b>Carpintería previa:</b> ${escapeHTML(q.craft)}</div>`:''}</div><div class="btn-row"><button class="btn primary" data-action="mini-next" data-id="${l.id}">${i+1===qs.length?'Ver resultado':'Siguiente →'}</button></div>`:`<div class="btn-row"><button class="btn ghost sm" data-action="mini-hint" data-id="${l.id}">${session.hint?'Ocultar pista':'Ver pista'}</button></div>${session.hint?`<div class="hint">${escapeHTML(q.tip)}</div>`:''}`}</article>`;
}


function lessonView(){
 const l=getLesson(st.lesson),extra=DEEP_GUIDE[l.id],shown=lessonSteps[l.id]||0,detail=!!lessonDetailed[l.id];
 const guide=SCAFFOLDS[l.id]||[],pos=LESSONS.findIndex(x=>x.id===l.id),prev=LESSONS[pos-1],next=LESSONS[pos+1];
 const deep=(l.steps||[]).map((math,i)=>({title:extra?.reasons[i]?.[0]||`Paso ${i+1}`,math,why:extra?.reasons[i]?.[1]||l.recipe[Math.min(i,l.recipe.length-1)],detail:ORIGIN_DETAILS[l.id]?.[i]||guide[2]}));
 return `<button class="btn flat sm" data-action="tab" data-tab="ruta">← Lecciones</button><div class="lesson-identity"><span class="tag">SEMANA ${l.week}</span><span class="tag grey">${escapeHTML(l.unit)}</span><span class="tag muted-tag">${escapeHTML(l.level)}</span></div><h1 class="h1">${escapeHTML(l.name)}</h1>
 <section class="lesson-layout"><div class="reading">
 <article class="panel theory-card"><div class="eyebrow">01 / TEORÍA</div><h2 class="h2">Qué estás resolviendo</h2><p>${escapeHTML(l.concept)}</p>${texBlock(l.formula)}${explorer(l.id)}<div class="theory-facts"><div><strong>Cómo reconocerlo</strong><p>${escapeHTML(guide[0]||extra?.when||'')}</p></div><div><strong>Por qué este método</strong><p>${escapeHTML(guide[1]||extra?.idea||'')}</p></div></div></article>
 <article class="panel"><div class="eyebrow">02 / ESTRATEGIA</div><h2 class="h2">Antes de calcular</h2><div class="strategy-list"><div class="strategy-item"><span>01</span><div><b>Identifica</b><p>${escapeHTML(guide[0]||'Identifica el patrón de la ecuación.')}</p></div></div><div class="strategy-item"><span>02</span><div><b>Elige</b><p>${escapeHTML(guide[1]||'Aplica el método que corresponde al patrón.')}</p></div></div><div class="strategy-item"><span>03</span><div><b>Prepara</b><p>${escapeHTML(guide[2]||'Simplifica y comprueba los signos.')}</p></div></div><div class="strategy-item"><span>04</span><div><b>Comprueba</b><p>${escapeHTML(guide[3]||'Sustituye el resultado y revisa la EDO.')}</p></div></div></div><div class="method-chips">${l.recipe.map((s,i)=>`<span>${i+1}. ${escapeHTML(s)}</span>`).join('')}</div></article>
 <article class="panel"><div class="eyebrow">03 / EJERCICIO RESUELTO</div><div class="section-line"><h2 class="h2">Paso a paso</h2><button class="btn ${detail?'primary':'ghost'} sm" data-action="toggle-lesson-detail" data-id="${l.id}">${detail?'Ocultar detalle':'Ver resolución detallada'}</button></div><div class="problem-block">${texBlock(l.example)}</div>${detail?`<div class="detail-guide"><strong>Cómo abordarlo</strong><div><b>Patrón:</b> ${escapeHTML(guide[0]||'')}</div><div><b>Elección:</b> ${escapeHTML(guide[1]||'')}</div><div><b>Preparación:</b> ${escapeHTML(guide[2]||'')}</div></div>`:''}
 ${renderedProcess(deep,shown,detail)}<div class="btn-row">${shown<deep.length?`<button class="btn primary sm" data-action="reveal-lesson-step" data-id="${l.id}">Mostrar paso ${shown+1} →</button><button class="btn ghost sm" data-action="reveal-lesson-all" data-id="${l.id}">Ver todos los pasos</button>`:`<button class="btn ghost sm" data-action="hide-lesson-steps" data-id="${l.id}">↻ Resolver otra vez</button>`}</div>
 ${shown===deep.length?`<div class="final-answer"><span>RESULTADO</span>${texBlock(l.result)}</div><div class="specific-tip"><strong>Truco del tema</strong><p>${escapeHTML(extra?.tip||guide[2]||'')}</p></div><div class="note-box"><strong>Evita este error</strong><div>${escapeHTML(l.error)}</div></div>`:''}</article>
 ${miniQuiz(l)}
 <article class="panel"><div class="eyebrow">06 / APUNTES</div><h2 class="h2">Mis notas</h2><textarea class="notes" id="notes" data-lesson="${l.id}" placeholder="Apuntes de este método…">${escapeHTML(st.notes[l.id]||'')}</textarea></article>
 <div class="lesson-nav">${prev?`<button class="btn ghost" data-action="open-lesson" data-id="${prev.id}">← ${escapeHTML(prev.name)}</button>`:'<span></span>'}${next?`<button class="btn primary" data-action="open-lesson" data-id="${next.id}">${escapeHTML(next.name)} →</button>`:'<button class="btn primary" data-action="tab" data-tab="examenes">Simulacro →</button>'}</div>
 </div>${asideLesson(l)}</section>`;
}

const AUX_TIPS=[
 {name:'Factor común',math:'ax+ay=a(x+y)',use:'Antes de resolver productos o integrar polinomios',why:'Extrae el factor repetido; simplifica la expresión sin cambiar sus raíces.',example:'6x²+9x=3x(2x+3)',error:'Dividir entre x puede eliminar x=0 de las soluciones.'},
 {name:'Diferencia de cuadrados',math:'a^2-b^2=(a-b)(a+b)',use:'Característica r²−k²=0',why:'Permite reconocer dos raíces opuestas sin fórmula cuadrática.',example:'r²−9=(r−3)(r+3)',error:'a²+b² no se factoriza igual sobre los reales.'},
 {name:'Trinomio cuadrático',math:'x^2+(p+q)x+pq=(x+p)(x+q)',use:'Características de segundo orden',why:'Busca dos números con suma b y producto c cuando el coeficiente cuadrático es 1.',example:'r²−6r+5=(r−1)(r−5)',error:'Compara también el signo del término independiente.'},
 {name:'Cuadrado perfecto',math:'a^2\\pm2ab+b^2=(a\\pm b)^2',use:'Raíces dobles de segundo orden y Cauchy–Euler',why:'El término del medio debe ser exactamente el doble del producto.',example:'r²−4r+4=(r−2)²',error:'Con raíz doble, la segunda solución tiene factor x.'},
 {name:'Fórmula cuadrática',math:'x=\\frac{-b\\pm\\sqrt{b^2-4ac}}{2a}',use:'Cuando el trinomio no factoriza fácilmente',why:'El discriminante clasifica raíces reales, repetidas y complejas.',example:'r²+2r+5=0 ⇒ r=−1±2i',error:'Respeta los paréntesis al sustituir b negativo.'},
 {name:'Fracciones parciales',math:'\\frac{1}{(s-a)(s-b)}=\\frac{A}{s-a}+\\frac{B}{s-b}',use:'Transformada inversa de Laplace',why:'Separar factores permite usar directamente las tablas de transformadas.',example:'1/[(s−1)(s+2)]=⅓/(s−1)−⅓/(s+2)',error:'Si hay factor repetido incluye todas las potencias.'},
 {name:'Triángulo rectángulo',math:'a^2+b^2=c^2',use:'Cálculo de magnitudes, áreas y razones trigonométricas',why:'La hipotenusa es la longitud opuesta al ángulo recto.',example:'Catetos 3 y 4 ⇒ hipotenusa 5',error:'No intercambies hipotenusa con un cateto.'},
 {name:'Identidad trigonométrica',math:'\\sin^2x+\\cos^2x=1',use:'Wronskiano de cos x y sen x; simplificación trigonométrica',why:'Es el teorema de Pitágoras aplicado al círculo unitario.',example:'W(cos x, sen x)=cos²x+sen²x=1',error:'Es incorrecto reemplazar sen²+cos² por 2.'},
 {name:'Ángulos en radianes',math:'180^\\circ=\\pi\\;\\text{rad}',use:'Derivar/integrar sen, cos; período 2π/ω',why:'Las fórmulas de cálculo trigonométrico estándar asumen radianes.',example:'60°=π/3; 90°=π/2',error:'No introduzcas 90 en cos(x) si querías π/2.'},
 {name:'Identidad y derivadas trigonométricas',math:'(\\sin x)\\prime=\\cos x,\\quad (\\cos x)\\prime=-\\sin x',use:'Verificar soluciones con raíces complejas',why:'Al derivar cos aparece un signo menos; al derivar sen no.',example:'d/dx sen(3x)=3cos(3x)',error:'Multiplica por la derivada interna: regla de la cadena.'},
 {name:'Sustitución u',math:'\\int f(g(x))g\\prime(x)\\,dx=\\int f(u)\\,du',use:'Integrar factores integrantes y ecuaciones separables',why:'Se identifica una derivada interna que acompaña a la expresión exterior.',example:'∫2x·e^(x²) dx=e^(x²)+C',error:'Comprueba que esté presente el factor de la derivada interna.'},
 {name:'Integración por partes',math:'\\int u\\,dv=uv-\\int v\\,du',use:'Bernoulli, variación de parámetros y transformadas',why:'Conviene cuando derivar una parte simplifica el producto.',example:'∫xeˣ dx=xeˣ−eˣ+C',error:'No pierdas el signo menos al restar la integral restante.'}
];
let builderMode='guided',chosenBuilder='lineal',typedEquation='',withInitial=true,customShown=0,currentSolution=null,solutionError='',toolMode='factor',toolParams={a:1,b:-6,c:5,opp:3,adj:4,angle:30},toolShown=0,toolResult=null,toolError='';
let customParams=Object.fromEntries(Object.entries(SOLVER_TYPES).map(([id,obj])=>[id,Object.fromEntries(obj.fields.map(([key,,value])=>[key,value]))]));
function solutionPane(solution,shown,action){return `<div class="solution-output"><div class="eyebrow">RESULTADO DEL EJERCICIO</div><div class="problem-block">${texBlock(solution.equation)}</div>${renderedProcess(solution.steps,shown)}<div class="btn-row">${shown<solution.steps.length?`<button class="btn primary sm" data-action="${action}-next">Mostrar paso ${shown+1} →</button><button class="btn ghost sm" data-action="${action}-all">Ver todo</button>`:`<button class="btn ghost sm" data-action="${action}-reset">↻ Ocultar pasos</button>`}</div>${shown>=solution.steps.length?`<div class="final-answer"><span>SOLUCIÓN</span>${texBlock(solution.result)}</div>${solution.verify?`<div class="specific-tip"><strong>Comprobación</strong>${texBlock(solution.verify)}</div>`:''}${solution.tip?`<div class="specific-tip"><strong>Consejo</strong><p>${escapeHTML(solution.tip)}</p></div>`:''}`:''}</div>`}

const BUILDER_MATH={lineal:"y'+ay=b",separable:"y'=kx^ny",segundo:"Ay''+By'+Cy=0",laplace:"y'+ay=b",crecimiento:"y'=ky",forzado:"y'+ay=ce^{kx}",euler:"Ax^2y''+Bxy'+Cy=0"};
const FIELD_MATH={a:'a',b:'b',A:'A',B:'B',C:'C',c:'c',k:'k',n:'n',y0:'y(0)',v0:"y'(0)",y1:'y(1)',v1:"y'(1)"};
function fieldReason(f,type){const dict={a:'Coeficiente de y en primer orden.',b:'Término independiente o forzamiento constante.',A:'Coeficiente de y″: no puede ser cero.',B:'Coeficiente de y′.',C:'Coeficiente que multiplica a y.',c:'Amplitud de la fuerza exponencial.',k:'Tasa de crecimiento o exponente del forzamiento.',n:'Exponente entero de x, entre 0 y 8.',y0:'Valor de y al comenzar en x=0.',v0:'Pendiente inicial y′(0).',y1:'Valor de y cuando x=1.',v1:'Pendiente y′(1).'};return dict[f]||f;}
function builderReadme(type){const map={lineal:['Identifica y′+a y=b.','Para b constante, considera primero la particular b/a; si a=0 integra directamente.'],separable:['El lado derecho es un producto de x e y.','Separa dy/y y x^n dx. Antes de dividir comprueba y=0.'],segundo:['Coeficientes constantes en y″, y′, y.','Prueba y=e^{rx}; factoriza Ar²+Br+C y decide según el discriminante.'],laplace:['PVI con valores iniciales conocidos.','Transforma y′ en sY−y(0); despeja Y(s) e invierte.'],crecimiento:['La velocidad es proporcional a la cantidad actual.','Usa y=Ce^{kx}; k positivo crece, k negativo decae.'],forzado:['Lineal de primer orden con término exponencial.','Multiplica por e^{ax}; si a+k=0 aparece resonancia y un factor x.'],euler:['Los coeficientes llevan x², x y un término constante.','Prueba y=x^m, resuelve la indicial y trabaja para x>0.']};const [recognize,reason]=map[type]||[];return `<div class="builder-explanation"><b>Reconoce el patrón</b><p>${escapeHTML(recognize||'')}</p><b>Qué hacer y por qué</b><p>${escapeHTML(reason||'')}</p>${explorer('builder_'+type)}</div>`;}

function builderPreview(){try{const r=customSolve(chosenBuilder,customParams[chosenBuilder],withInitial);return r.error?null:r.equation}catch{return null}}
function constructorView(){const conf=SOLVER_TYPES[chosenBuilder],h=st.customHistory||[],preview=builderPreview();
 return `<div class="eyebrow">CREA TU EJERCICIO</div><h1 class="h1">Resolver ecuaciones diferenciales</h1>
 <section class="work-layout"><div class="work-stack">
 <article class="panel builder-main">
 <div class="builder-mode-head"><h2 class="h2">¿Cómo quieres introducirla?</h2><p class="muted small">Los dos modos llevan al mismo solucionador.</p></div>
 <div class="builder-mode-switch" role="group" aria-label="Modo de entrada"><button class="builder-mode-btn ${builderMode==='guided'?'active':''}" data-action="builder-mode" data-id="guided" aria-pressed="${builderMode==='guided'}"><strong>◫ Constructor guiado</strong><small>Elige un tipo y cambia sus valores.</small></button><button class="builder-mode-btn ${builderMode==='manual'?'active':''}" data-action="builder-mode" data-id="manual" aria-pressed="${builderMode==='manual'}"><strong>✎ Escritura directa</strong><small>Copia una ecuación de tu guía.</small></button></div>
 ${builderMode==='guided'?`
 <div class="section-line"><h3 class="h3 space-top">1. Selecciona la familia</h3><span class="muted small">7 casos disponibles</span></div>
 <div class="builder-types">${Object.entries(SOLVER_TYPES).map(([id,s])=>`<button class="type-select ${id===chosenBuilder?'active':''}" data-action="builder-type" data-id="${id}" aria-pressed="${id===chosenBuilder}"><strong>${escapeHTML(s.name)}</strong><span>${tex(BUILDER_MATH[id]||s.formula||s.description)}</span></button>`).join('')}</div>
 ${explorer('builder_'+chosenBuilder)}<div class="builder-explanation simple-help"><b>Cómo reconocerla</b><p>${escapeHTML(({lineal:'Aparecen y′ y y con coeficientes constantes; a la derecha hay un número.',separable:'El lado derecho es un producto k·xⁿ·y.',segundo:'Aparecen y″, y′ y y con coeficientes constantes; todo igualado a cero.',laplace:'Ecuación lineal de primer orden con un valor inicial: se transformará al dominio s.',crecimiento:'La variación y′ es proporcional a la cantidad y.',forzado:'La ecuación lineal tiene un término exponencial e^(kx).',euler:'Cada derivada está acompañada por la potencia correspondiente de x.'})[chosenBuilder])}</p><b>Por qué se usa ese método</b><p>${escapeHTML(({lineal:'Factor integrante (o solución particular constante) porque es lineal.',separable:'Separación de variables: cada lado queda con una sola variable.',segundo:'Ecuación característica: convierte el problema en una ecuación algebraica.',laplace:'La transformada incorpora la condición inicial en la ecuación algebraica.',crecimiento:'La proporcionalidad produce una ley exponencial.',forzado:'Factor integrante y regla del producto para integrar el forzamiento.',euler:'Sustitución y=x^m, porque las potencias de x se simplifican.'})[chosenBuilder])}</p></div>
 <h3 class="h3 space-top">2. Define los valores</h3>
 <div class="input-grid">${conf.fields.map(([id,label,def])=>`<label class="field"><span>${tex(FIELD_MATH[id]||label)} <i class="field-question" title="${escapeHTML(fieldReason(id,chosenBuilder))}" aria-label="${escapeHTML(fieldReason(id,chosenBuilder))}">ⓘ</i></span><input type="number" step="any" inputmode="decimal" data-builder-field="${id}" value="${escapeHTML(customParams[chosenBuilder][id]??def)}" /></label>`).join('')}</div>
 <label class="check-line"><input id="builder-ic" type="checkbox" ${withInitial?'checked':''} ${chosenBuilder==='laplace'?'disabled title="Laplace requiere condición inicial"':''}/> ${chosenBuilder==='euler'?'Aplicar condiciones iniciales en x=1':'Aplicar condiciones iniciales'}</label>
 <div class="live-equation" aria-live="polite"><div><span class="eyebrow">3 / TU ECUACIÓN</span><p class="muted small">Se actualiza al modificar los coeficientes.</p></div><div id="builder-equation-preview">${preview?texBlock(preview):'<span class="muted small">Introduce valores válidos para ver la ecuación.</span>'}</div></div>
 <div class="btn-row"><button class="btn primary" data-action="builder-solve">Resolver paso a paso →</button><button class="btn ghost" data-action="builder-new">Restablecer</button></div>`:
 `<div class="manual-builder"><h3 class="h3">Escribe una ecuación completa</h3><label class="field" for="free-equation"><span>Separa la ecuación y las condiciones iniciales con comas.</span></label><input id="free-equation" class="manual-input" type="text" autocomplete="off" spellcheck="false" value="${escapeHTML(typedEquation)}" placeholder="y'+2y=6, y(0)=1"/><div class="input-preview"><span>Texto introducido</span><span id="typed-preview">${escapeHTML(typedEquation||'y′+2y=6, y(0)=1')}</span></div><div class="manual-help"><strong>El formato admitido actualmente</strong><p>Lineales con coeficientes constantes; separables del tipo y′=kxⁿy; homogéneas de segundo orden con coeficientes constantes.</p><p><b>Símbolos:</b> usa el apóstrofo ' para derivar, ^ para exponentes, y(0) para una condición inicial. Ejemplo: y''-6y'+5y=0, y(0)=2, y'(0)=6.</p></div><div class="example-chips">${["y'+2y=6, y(0)=1","y'=2xy, y(0)=3","y''-6y'+5y=0, y(0)=2, y'(0)=6"].map((v,i)=>`<button class="chip" data-action="builder-example" data-index="${i}">${escapeHTML(v)}</button>`).join('')}</div><div class="btn-row"><button class="btn primary" data-action="builder-parse">Interpretar y resolver →</button></div></div>`}
 </article>
 ${solutionError?`<div class="input-error" role="alert">${escapeHTML(solutionError)}</div>`:''}
 ${currentSolution?solutionPane(currentSolution,customShown,'builder-step'):''}
 </div><aside class="work-side"><article class="panel"><div class="eyebrow">HISTORIAL LOCAL</div>${h.length?h.map((entry,i)=>`<button class="history-item" data-action="builder-history" data-index="${i}"><strong>${escapeHTML(entry.typeLabel)}</strong><small>${escapeHTML(entry.display||'Ejercicio guardado')}</small></button>`).join(''):'<p class="muted small">Sin ejercicios guardados.</p>'}</article><article class="panel"><strong>Procedimientos relacionados</strong><div class="quick-links"><button data-action="open-lesson" data-id="s2">Variables separables →</button><button data-action="open-lesson" data-id="s4">Lineales →</button><button data-action="open-lesson" data-id="s8">Característica →</button><button data-action="open-lesson" data-id="s13">Laplace →</button></div></article></aside></section>`;
}
function helpersView(){const names=[['factor','Factorizar'],['geo','Geometría'],['trig','Trigonometría']];return `<div class="eyebrow">BASE MATEMÁTICA</div><h1 class="h1">Herramientas y trucos</h1><div class="filterbar">${names.map(([id,label])=>`<button class="filter ${id===toolMode?'active':''}" data-action="tool-tab" data-id="${id}">${label}</button>`).join('')}</div><section class="two-col"><article class="panel"><h2 class="h2">${toolMode==='factor'?'Calculadora de trinomios':toolMode==='geo'?'Triángulo rectángulo':'Círculo trigonométrico'}</h2><div class="input-grid">${(toolMode==='factor'?[['a','a'],['b','b'],['c','c']]:toolMode==='geo'?[['opp','Cateto opuesto'],['adj','Cateto adyacente']]:[['angle','Ángulo (grados)']]).map(([k,label])=>`<label class="field"><span>${label}</span><input type="number" step="any" data-tool-field="${k}" value="${escapeHTML(toolParams[k])}" /></label>`).join('')}</div><div class="btn-row"><button class="btn primary" data-action="tool-solve">Calcular y explicar →</button></div>${toolError?`<div class="input-error" role="alert">${escapeHTML(toolError)}</div>`:''}${toolResult?solutionPane(toolResult,toolShown,'tool-step'):''}</article><article class="panel"><div class="eyebrow">FORMULARIO RÁPIDO</div>${AUX_TIPS.filter(x=>toolMode==='factor'?['Factor común','Diferencia de cuadrados','Trinomio cuadrático','Cuadrado perfecto','Fórmula cuadrática'].includes(x.name):toolMode==='geo'?x.name==='Triángulo rectángulo':['Ángulos en radianes','Identidad trigonométrica','Identidad y derivadas trigonométricas'].includes(x.name)).map(x=>`<div class="helper-quick"><strong>${escapeHTML(x.name)}</strong>${texBlock(x.math)}<p class="small muted">${escapeHTML(x.use)}</p></div>`).join('')}</article></section>
 <div class="section-head"><h2>Reglas y aplicaciones</h2></div><section class="aux-grid">${AUX_TIPS.map(x=>`<article class="aux-card"><div class="eyebrow">${escapeHTML(x.use)}</div><h3>${escapeHTML(x.name)}</h3>${texBlock(x.math)}<p><strong>Motivo:</strong> ${escapeHTML(x.why)}</p><p><strong>Ejemplo:</strong> ${escapeHTML(x.example)}</p><div class="aux-warning"><strong>Cuidado:</strong> ${escapeHTML(x.error)}</div></article>`).join('')}</section>`;}
function home(){const next=LESSONS.find(l=>!st.done.includes(l.id))||LESSONS[0];return `<div class="eyebrow">MATEMÁTICA IV · ECUACIONES DIFERENCIALES</div><h1 class="h1">Tu espacio de estudio</h1><section class="compact-actions"><button class="action-tile" data-action="open-lesson" data-id="${next.id}"><span class="action-icon">∂</span><strong>Continuar lección</strong><small>Semana ${next.week} · ${escapeHTML(next.name)}</small><span>→</span></button><button class="action-tile" data-action="tab" data-tab="constructor"><span class="action-icon">✎</span><strong>Crear un ejercicio</strong><small>Coeficientes, condiciones y resolución</small><span>→</span></button><button class="action-tile" data-action="tab" data-tab="herramientas"><span class="action-icon">∑</span><strong>Herramientas</strong><small>Factorización, geometría y trigonometría</small><span>→</span></button></section><section class="hero-stats"><div class="stat"><div class="stat-top">Lecciones</div><div class="stat-value">${st.done.length}<span class="muted" style="font-size:14px"> / ${LESSONS.length}</span></div></div><div class="stat"><div class="stat-top">Respuestas</div><div class="stat-value">${st.attempts.length}</div></div><div class="stat"><div class="stat-top">Aciertos</div><div class="stat-value">${st.attempts.length?pct(successCount(),st.attempts.length)+'%':'—'}</div></div></section><div class="section-head"><h2>Temario</h2><button class="btn flat" data-action="tab" data-tab="ruta">Ver lecciones →</button></div><section class="grid-courses">${units.map((u,i)=>{let ls=LESSONS.filter(l=>l.unit===u);return `<button class="course-card" data-action="unit" data-unit="${escapeHTML(u)}"><div class="course-icon" style="color:${UNIT_META[u].color}">${['∑','∫','ƒ','λ','ℒ'][i]}</div><h3>${u}</h3><div class="course-foot"><span>${doneCount(u)} / ${ls.length} lecciones</span><span>→</span></div><div class="progress-mini"><span style="width:${pct(doneCount(u),ls.length)}%"></span></div></button>`}).join('')}</section>`}
function asideLesson(l){let count=lessonQuestions(l.id).length;return `<aside class="lesson-aside"><div class="panel"><div class="eyebrow">PROGRESO</div><button class="btn ${st.done.includes(l.id)?'ghost':'primary'}" style="width:100%;white-space:normal" data-action="toggle-done" data-id="${l.id}">${st.done.includes(l.id)?'✓ Completada':'Marcar como aprendida'}</button></div><div class="panel"><div class="eyebrow">PRACTICAR</div><button class="btn ghost sm" data-action="mini-jump" data-id="${l.id}">Minicuestionario de 5 →</button><button class="btn flat sm" data-action="practice-lesson" data-id="${l.id}">${count} preguntas base →</button></div><div class="panel"><div class="eyebrow">GUÍA ORIGINAL</div><p class="small muted">Págs. ${escapeHTML(l.pages)}</p><a class="doc-link" href="${docHref(l.source)}" target="_blank" rel="noopener">Abrir PDF ↗</a></div><div class="panel"><button class="btn flat" data-action="tab" data-tab="herramientas">Herramientas matemáticas →</button></div></aside>`}

function render(){if(exam&&!exam.result&&Date.now()>exam.end)finishExam();let title=st.tab==='leccion'?getLesson(st.lesson).name:undefined;$('#app').innerHTML=`<div class="shell">${sidebar()}<main class="main">${header(title)}<div class="page" id="content">${st.tab==='inicio'?home():st.tab==='ruta'?route():st.tab==='metodos'?methods():st.tab==='leccion'?lessonView():st.tab==='practica'?practice():st.tab==='examenes'?exams():st.tab==='biblioteca'?library():st.tab==='constructor'?constructorView():st.tab==='herramientas'?helpersView():home()}</div></main></div>${st.search?searchModal():''}`;typeset(); if(st.search){setTimeout(()=>$('#global-search')?.focus(),0)} }
function searchModal(){const q=st.query.toLowerCase();const hits=LESSONS.filter(l=>(l.name+' '+l.unit+' '+l.summary+' '+l.week).toLowerCase().includes(q)).slice(0,9);return `<div class="search-modal" id="search-overlay"><div class="search-box" role="dialog" aria-modal="true" aria-label="Buscar lecciones"><input id="global-search" class="searchbox-input" placeholder="Buscar tema, método o semana…" value="${escapeHTML(st.query)}"/><div class="search-results" id="search-results">${searchHitList(hits)}</div><div class="small muted" style="padding:10px 17px;border-top:1px solid var(--line)">Esc para cerrar · selecciona un tema para abrirlo</div></div></div>`}
function searchHitList(hits){return hits.length?hits.map(l=>`<button class="search-result" data-action="open-lesson" data-id="${l.id}"><strong>${escapeHTML(l.name)}</strong><small>Semana ${l.week} · ${escapeHTML(l.unit)}</small></button>`).join(''):'<div class="empty">No se encontraron temas.</div>'}
function formatTime(v){return String(Math.floor(v/60)).padStart(2,'0')+':'+String(v%60).padStart(2,'0')}

function startExam(){const cfg=TIERS[st.examTier-1],n=cfg.count;
 const copy=QUESTIONS.filter(q=>q.tier>=cfg.from&&q.tier<=cfg.to);
 for(let i=copy.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]];}
 const picked=[],seen=new Set();for(const q of copy){if(!seen.has(q.lesson)){picked.push(q);seen.add(q.lesson);}if(picked.length>=n)break;}
 for(const q of copy){if(picked.length>=n)break;if(!picked.some(x=>x.id===q.id))picked.push(q);}
 exam={questions:picked,answers:Array(picked.length).fill(null),freeAnswers:Array(picked.length).fill(''),works:Array(picked.length).fill(''),selfMarks:Array(picked.length).fill(null),workOpen:st.examTier>=4,index:0,end:Date.now()+cfg.minutes*60000,result:false,tier:st.examTier};saveExam();render();window.scrollTo({top:0,behavior:'instant'});
}

function finishExam(){if(!exam||exam.result)return;exam.result=true;if(!openAnswerMode())exam.questions.forEach((q,i)=>{const ans=exam.answers[i];if(ans!==null)st.attempts.push({q:q.id,correct:ans===q.correct,chosen:ans,ts:new Date().toISOString(),exam:true})});save();saveExam();render();window.scrollTo({top:0,behavior:'instant'})}
function exportProgress(){let content=JSON.stringify({app:'Deriva MAT415',exported:new Date().toISOString(),lecciones_completadas:st.done,notas:st.notes,intentos:st.attempts,marcadores:st.bookmarks,mini_cuestionarios:st.miniScores,ejercicios_creados:st.customHistory},null,2);let blob=new Blob([content],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='deriva-progreso.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast('Progreso exportado.');}
const actions={
 'toggle-lesson-detail':el=>{let id=el.dataset.id;lessonDetailed[id]=!lessonDetailed[id];render()},
 'mini-hint':el=>{let s=getMini(el.dataset.id);s.hint=!s.hint;render()},
 'mini-answer':el=>{const id=el.dataset.id,s=getMini(id),q=s.questions[s.index];if(!q||s.answers[s.index]!==undefined)return;s.answers[s.index]=Number(el.dataset.choice);s.hint=false;st.attempts.push({q:q.id,correct:s.answers[s.index]===q.correct,chosen:s.answers[s.index],ts:new Date().toISOString(),mini:true});save();render()},
 'mini-next':el=>{const id=el.dataset.id,s=getMini(id);if(s.answers[s.index]===undefined)return;s.index=Math.min(s.index+1,s.questions.length);if(s.index===s.questions.length){st.miniScores[id]={correct:s.questions.filter((q,i)=>s.answers[i]===q.correct).length,total:s.questions.length,date:new Date().toISOString()};save();}render()},
 'mini-retry':el=>{delete miniSessions[el.dataset.id];render()},
 'mini-jump':()=>{document.getElementById('mini-quiz')?.scrollIntoView({behavior:'smooth',block:'start'})},
 'exam-tier':el=>{st.examTier=Number(el.dataset.id);render()},
 'practice-tier':el=>{st.practiceTier=Number(el.dataset.id);randomQuestion();render()},

 'builder-mode':el=>{builderMode=el.dataset.id;currentSolution=null;solutionError='';customShown=0;render()},
 'builder-type':el=>{chosenBuilder=el.dataset.id;withInitial=true;currentSolution=null;solutionError='';customShown=0;render()},
 'builder-solve':()=>{currentSolution=customSolve(chosenBuilder,customParams[chosenBuilder],withInitial);solutionError=currentSolution.error||'';if(solutionError)currentSolution=null;else{customShown=0;st.customHistory.unshift({type:chosenBuilder,typeLabel:SOLVER_TYPES[chosenBuilder].name,display:currentSolution.equation,values:{...customParams[chosenBuilder]},withIC:withInitial});st.customHistory=st.customHistory.slice(0,15);save()}render()},
 'builder-new':()=>{customParams[chosenBuilder]=Object.fromEntries(SOLVER_TYPES[chosenBuilder].fields.map(([k,,v])=>[k,v]));withInitial=true;currentSolution=null;customShown=0;solutionError='';typedEquation='';render()},
 'builder-parse':()=>{const res=parseEquation(typedEquation);if(res.error){solutionError=res.error;currentSolution=null;render();return;}chosenBuilder=res.type;customParams[chosenBuilder]={...customParams[chosenBuilder],...res.values};withInitial=res.withIC;currentSolution=customSolve(chosenBuilder,customParams[chosenBuilder],withInitial);solutionError=currentSolution.error||'';if(solutionError)currentSolution=null;else{customShown=0;st.customHistory.unshift({type:chosenBuilder,typeLabel:SOLVER_TYPES[chosenBuilder].name,display:typedEquation,values:{...customParams[chosenBuilder]},withIC:withInitial});st.customHistory=st.customHistory.slice(0,15);save()}render()},
 'builder-example':el=>{const ex=["y'+2y=6, y(0)=1","y'=2xy, y(0)=3","y''-6y'+5y=0, y(0)=2, y'(0)=6"];typedEquation=ex[Number(el.dataset.index)];const e=document.getElementById('free-equation');if(e)e.value=typedEquation;},
 'builder-history':el=>{builderMode='guided';const ent=st.customHistory[Number(el.dataset.index)];if(!ent)return;chosenBuilder=ent.type;customParams[chosenBuilder]={...ent.values};withInitial=ent.withIC;currentSolution=customSolve(chosenBuilder,customParams[chosenBuilder],withInitial);solutionError=currentSolution.error||'';customShown=0;render()},
 'builder-step-next':()=>{if(currentSolution){customShown=Math.min(customShown+1,currentSolution.steps.length);render()}},
 'builder-step-all':()=>{if(currentSolution){customShown=currentSolution.steps.length;render()}},
 'builder-step-reset':()=>{customShown=0;render()},
 'tool-tab':el=>{toolMode=el.dataset.id;toolResult=null;toolError='';toolShown=0;render()},
 'tool-solve':()=>{toolResult=toolMode==='factor'?factorSolve(toolParams.a,toolParams.b,toolParams.c):toolMode==='geo'?triangleSolve(toolParams.opp,toolParams.adj):trigSolve(toolParams.angle);toolError=toolResult.error||'';if(toolError)toolResult=null;toolShown=0;render()},
 'tool-step-next':()=>{if(toolResult){toolShown=Math.min(toolShown+1,toolResult.steps.length);render()}},
 'tool-step-all':()=>{if(toolResult){toolShown=toolResult.steps.length;render()}},
 'tool-step-reset':()=>{toolShown=0;render()},
 'tab':el=>setTab(el.dataset.tab),
 'week':el=>openLesson(LESSONS.find(l=>l.week===Number(el.dataset.week)).id),
 'open-lesson':el=>{st.search=false;st.query='';openLesson(el.dataset.id)},
 'unit':el=>{st.filter=el.dataset.unit;setTab('ruta')},
 'filter':el=>{st.filter=el.dataset.filter;render()},
 'toggle-done':el=>{st.done=st.done.includes(el.dataset.id)?st.done.filter(x=>x!==el.dataset.id):[...st.done,el.dataset.id];save();render();showToast('Progreso actualizado.')},
 'practice-lesson':el=>{st.practiceTier=1;st.topic=getLesson(el.dataset.id).unit;st.lessonFocus=el.dataset.id;st.reviewOnly=false;randomQuestion();setTab('practica')},
 'topic':el=>{st.topic=el.dataset.topic;st.lessonFocus=null;randomQuestion();render()},
 'clear-focus':()=>{st.lessonFocus=null;randomQuestion();render()},
 'reveal-lesson-step':el=>{const l=getLesson(el.dataset.id);lessonSteps[l.id]=Math.min(l.steps.length,(lessonSteps[l.id]||0)+1);render()},
 'reveal-lesson-all':el=>{const l=getLesson(el.dataset.id);lessonSteps[l.id]=l.steps.length;render()},
 'hide-lesson-steps':el=>{lessonSteps[el.dataset.id]=0;render()},
 'toggle-review':()=>{st.reviewOnly=!st.reviewOnly;randomQuestion();render()},
 'hint':()=>{pr.hint=!pr.hint;render()},
 'answer':el=>{if(!pr.q||pr.chosen!==null)return;pr.chosen=Number(el.dataset.index);st.attempts.push({q:pr.q.id,correct:pr.chosen===pr.q.correct,chosen:pr.chosen,ts:new Date().toISOString(),exam:false});save();render()},
 'next-question':()=>{randomQuestion();render()},
 'expand-method':()=>{pr.expanded=!pr.expanded;render()},
 'bookmark':el=>{let id=el.dataset.id;st.bookmarks=st.bookmarks.includes(id)?st.bookmarks.filter(x=>x!==id):[...st.bookmarks,id];save();render()},
 'exam-type':el=>{st.examType=Number(el.dataset.n);render()},
 'exam-start':()=>startExam(),
 'exam-answer':el=>{if(!exam)return;exam.answers[exam.index]=Number(el.dataset.index);saveExam();render()},
 'exam-next':()=>{if(exam&&exam.index<exam.questions.length-1){exam.index++;saveExam();render();window.scrollTo({top:0,behavior:'instant'})}},
 'exam-prev':()=>{if(exam&&exam.index>0){exam.index--;saveExam();render();window.scrollTo({top:0,behavior:'instant'})}},
 'exam-finish':()=>finishExam(),
 'exam-reset':()=>{exam=null;saveExam();render()},
 'exam-goto':el=>{if(exam&&!exam.result){exam.index=Number(el.dataset.index);saveExam();render();window.scrollTo({top:0,behavior:'instant'})}},
 'exam-work-toggle':()=>{if(exam&&!exam.result){exam.workOpen=!exam.workOpen;saveExam();render()}},
 'exam-insert':el=>{const a=$('#exam-work');if(!a||!exam)return;const p=a.selectionStart,e=a.selectionEnd,t=el.dataset.symbol;a.value=a.value.slice(0,p)+t+a.value.slice(e);a.focus();a.setSelectionRange(p+t.length,p+t.length);exam.works[exam.index]=a.value;saveExam()},
 'exam-export-work':()=>exportExamWork(),
 'exam-self-check':el=>{if(!exam||!exam.result||!openAnswerMode())return;const i=Number(el.dataset.index),mark=el.dataset.mark==='yes';if(exam.selfMarks[i]===null)st.attempts.push({q:exam.questions[i].id,correct:mark,chosen:null,ts:new Date().toISOString(),exam:true,selfAssessed:true});else{const a=[...st.attempts].reverse().find(a=>a.q===exam.questions[i].id&&a.exam&&a.selfAssessed);if(a)a.correct=mark;}exam.selfMarks[i]=mark;save();saveExam();render()},
 'export':()=>exportProgress(),
 'reset-progress':()=>{if(!confirm('¿Borrar todas las lecciones, respuestas y notas guardadas en este navegador?'))return;st.notes={};st.done=[];st.attempts=[];st.bookmarks=[];st.flashKnown=[];st.customHistory=[];st.miniScores={};Object.keys(miniSessions).forEach(k=>delete miniSessions[k]);exam=null;saveExam();save();render();showToast('Progreso local borrado.')},
 'search-open':()=>{st.search=true;st.query='';render()},
 'search-close':()=>{st.search=false;st.query='';render()},
};
document.addEventListener('click',e=>{const actionEl=e.target.closest('[data-action]');if(actionEl){e.preventDefault();actions[actionEl.dataset.action]?.(actionEl)}else if(e.target.id==='search-overlay'){st.search=false;render()}});
document.addEventListener('input',e=>{if(e.target.dataset.builderField){customParams[chosenBuilder][e.target.dataset.builderField]=e.target.value;const p=$('#builder-equation-preview');if(p){const v=builderPreview();p.innerHTML=v?texBlock(v):'<span class="muted small">Introduce valores válidos.</span>';typeset()}}else if(e.target.dataset.toolField){toolParams[e.target.dataset.toolField]=e.target.value}else if(e.target.id==='free-equation'){typedEquation=e.target.value;const preview=$('#typed-preview');if(preview)preview.textContent=typedEquation}else if(e.target.dataset.examWork!==undefined&&exam&&!exam.result){exam.works[Number(e.target.dataset.examWork)]=e.target.value;saveExam()}else if(e.target.dataset.examFree!==undefined&&exam&&!exam.result){exam.freeAnswers[Number(e.target.dataset.examFree)]=e.target.value;saveExam();const n=$('.exam-current .practice-tools .muted');if(n)n.textContent=exam.questions.filter((_,i)=>isExamAnswered(i)).length+' de '+exam.questions.length+' respondidas';}else if(e.target.id==='notes'){st.notes[e.target.dataset.lesson]=e.target.value;save()}else if(e.target.id==='global-search'){st.query=e.target.value;const q=st.query.toLowerCase();$('#search-results').innerHTML=searchHitList(LESSONS.filter(l=>(l.name+' '+l.unit+' '+l.summary+' '+l.week).toLowerCase().includes(q)).slice(0,10))}});
document.addEventListener('change',e=>{if(e.target.id==='builder-ic'){withInitial=e.target.checked;currentSolution=null;solutionError='';render()}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();st.search=!st.search;st.query='';render()}else if(e.key==='Escape'&&st.search){st.search=false;st.query='';render()}else if(st.search&&e.key==='Enter'&&e.target.id==='global-search'){e.preventDefault();$('#search-results .search-result')?.click()}});
setInterval(()=>{if(exam&&!exam.result){let v=Math.ceil((exam.end-Date.now())/1000);if(v<=0){finishExam();showToast('Tiempo terminado; respuestas corregidas.')}else if($('#countdown')){$('#countdown').textContent=formatTime(v)}}},1000);
render();
})();
